insert into public.traduzioni_ui (namespace, chiave, it, de, fr, en, rm) values
('planning', 'griglia_guida.come_titolo', 'Come si costruisce', 'So baust du die Einheit auf', 'Comment construire la séance', 'How to build it', 'Co construir'),
('planning', 'griglia_guida.come_testo', 'Prendi un nome dall''elenco qui sotto, tienilo premuto e portalo dentro la sessione. Puoi prendere un intero gruppo, per esempio «Pulcini», oppure un atleta alla volta. Gli istruttori si portano allo stesso modo.', 'Nimm einen Namen aus der Liste unten, halte ihn gedrückt und zieh ihn in die Einheit. Du kannst eine ganze Gruppe nehmen, zum Beispiel «Pulcini», oder eine Athletin nach der anderen. Trainerinnen und Trainer ziehst du genauso hinein.', 'Prends un nom dans la liste ci-dessous, garde-le appuyé et amène-le dans la séance. Tu peux prendre un groupe entier, par exemple « Pulcini », ou un athlète à la fois. Les entraîneurs se déplacent de la même façon.', 'Pick a name from the list below, keep it pressed and carry it into the session. You can take a whole group, for example “Pulcini”, or one athlete at a time. Coaches are moved the same way.', 'Prenda in num da la glista sutvart, tegna el smatgà e al porta en la sesida. Ti pos prender ina gruppa entira, per exempel «Pulcini», u in atlet a la giada. Ils instructurs portas ti a medem moda.'),
('planning', 'griglia_guida.come_breve', 'Per aggiungere qualcuno: tieni premuto un nome dell''elenco e portalo dentro la sessione.', 'Um jemanden hinzuzufügen: Halte einen Namen gedrückt und zieh ihn in die Einheit.', 'Pour ajouter quelqu''un : garde un nom appuyé et amène-le dans la séance.', 'To add someone: keep a name pressed and carry it into the session.', 'Per agiuntar insatgi: tegna smatgà in num e al porta en la sesida.'),
('planning', 'griglia_guida.sessione_senza_nome', 'Sessione', 'Einheit', 'Séance', 'Session', 'Sesida'),
('planning', 'griglia_guida.istr_occupato', 'Già impegnato in: {{attivita}}', 'Bereits eingeteilt in: {{attivita}}', 'Déjà occupé dans : {{attivita}}', 'Already busy in: {{attivita}}', 'Gia occupà en: {{attivita}}'),
('planning', 'griglia_guida.istr_nessuna', 'Nessuna disponibilità dichiarata il {{giorno}}', 'Keine Verfügbarkeit angegeben am {{giorno}}', 'Aucune disponibilité déclarée le {{giorno}}', 'No availability declared on {{giorno}}', 'Nagina disponibilitad declerada il {{giorno}}'),
('planning', 'griglia_guida.istr_solo_fasce', 'Il {{giorno}} è disponibile solo {{fasce}}', 'Am {{giorno}} nur verfügbar {{fasce}}', 'Le {{giorno}}, disponible seulement {{fasce}}', 'On {{giorno}} only available {{fasce}}', 'Il {{giorno}} disponibel mo {{fasce}}'),
('planning', 'griglia_guida.disp_nessuna', 'Nessuna disponibilità dichiarata il {{giorno}}.', 'Keine Verfügbarkeit angegeben am {{giorno}}.', 'Aucune disponibilité déclarée le {{giorno}}.', 'No availability declared on {{giorno}}.', 'Nagina disponibilitad declerada il {{giorno}}.'),
('planning', 'griglia_guida.disp_fuori_fascia', '{{orario}} non rientra nella disponibilità dichiarata del {{giorno}} ({{fasce}}).', '{{orario}} liegt ausserhalb der angegebenen Verfügbarkeit am {{giorno}} ({{fasce}}).', '{{orario}} est en dehors de la disponibilité déclarée du {{giorno}} ({{fasce}}).', '{{orario}} is outside the availability declared for {{giorno}} ({{fasce}}).', '{{orario}} è ordaifer la disponibilitad declerada dal {{giorno}} ({{fasce}}).'),
('planning', 'griglia_guida.disp_generico', 'Fuori dalla disponibilità dichiarata.', 'Ausserhalb der angegebenen Verfügbarkeit.', 'En dehors de la disponibilité déclarée.', 'Outside the declared availability.', 'Ordaifer la disponibilitad declerada.'),
('planning', 'griglia_guida.forza_titolo', 'Fuori dalla disponibilità dichiarata', 'Ausserhalb der angegebenen Verfügbarkeit', 'En dehors de la disponibilité déclarée', 'Outside the declared availability', 'Ordaifer la disponibilitad declerada'),
('planning', 'griglia_guida.forza_puoi', 'Puoi procedere lo stesso: scrivi il motivo, che resta registrato con il tuo nome e la data.', 'Du kannst trotzdem fortfahren: Gib den Grund an, er wird mit deinem Namen und dem Datum gespeichert.', 'Tu peux quand même continuer : indique le motif, qui est enregistré avec ton nom et la date.', 'You can go ahead anyway: write the reason, which is recorded with your name and the date.', 'Ti pos cuntinuar tuttina: scriva il motiv, quel che vegn registrà cun tes num e la data.'),
('planning', 'griglia_guida.forza_non_puoi', 'Per procedere fuori dalla disponibilità dichiarata serve il Presidente o il Direttore Tecnico. Chiedi a loro, oppure scegli un altro orario o un''altra persona.', 'Um ausserhalb der angegebenen Verfügbarkeit fortzufahren, braucht es den Präsidenten oder den Technischen Direktor. Frag sie, oder wähle eine andere Zeit oder eine andere Person.', 'Pour continuer en dehors de la disponibilité déclarée, il faut le Président ou le Directeur technique. Demande-leur, ou choisis un autre horaire ou une autre personne.', 'To go ahead outside the declared availability you need the President or the Technical Director. Ask them, or choose another time or another person.', 'Per cuntinuar ordaifer la disponibilitad declerada dovri il president u il directur tecnic. Dumonda els, u tscherna in auter urari u in''autra persuna.'),
('planning', 'griglia_guida.forza_motivo_label', 'Motivo *', 'Grund *', 'Motif *', 'Reason *', 'Motiv *'),
('planning', 'griglia_guida.forza_motivo_esempio', 'Es. quel sabato c''è comunque, accordo con la gestione della pista', 'z. B. an diesem Samstag ist sie trotzdem da, Absprache mit der Eisbahn', 'Ex. elle est quand même là ce samedi, accord avec la patinoire', 'E.g. she is there that Saturday anyway, agreed with the rink', 'P.ex. quella sonda è ella tuttina qua, accord cun la plazza da patinar'),
('planning', 'griglia_guida.forza_annulla', 'Annulla', 'Abbrechen', 'Annuler', 'Cancel', 'Interrumper'),
('planning', 'griglia_guida.forza_procedi', 'Procedi con questo motivo', 'Mit diesem Grund fortfahren', 'Continuer avec ce motif', 'Go ahead with this reason', 'Cuntinuar cun quest motiv'),
('planning', 'griglia_guida.forza_ho_capito', 'Ho capito', 'Verstanden', 'J''ai compris', 'Got it', 'Jau hai chapì'),
('planning', 'griglia_guida.ric_solo', 'Questa sessione vale solo per {{giorno}}', 'Diese Einheit gilt nur für {{giorno}}', 'Cette séance vaut seulement pour {{giorno}}', 'This session is only for {{giorno}}', 'Questa sesida vala mo per {{giorno}}'),
('planning', 'griglia_guida.ric_ripeti', 'Ripetila ogni {{giorno}}', 'Jeden {{giorno}} wiederholen', 'La répéter chaque {{giorno}}', 'Repeat it every {{giorno}}', 'La repeter mintga {{giorno}}'),
('planning', 'griglia_guida.ric_fino_al', 'Ogni {{giorno}} fino al {{data}}', 'Jeden {{giorno}} bis {{data}}', 'Chaque {{giorno}} jusqu''au {{data}}', 'Every {{giorno}} until {{data}}', 'Mintga {{giorno}} fin ils {{data}}'),
('planning', 'griglia_guida.ric_generica', 'Ricorrente', 'Wiederkehrend', 'Récurrente', 'Recurring', 'Repetitiv')
